  var cachedLogoBase64 = null;
  function getLogoBase64() {
    if (cachedLogoBase64)
      return Promise.resolve(cachedLogoBase64);
    return window.electronAPI.getLogoBase64().then((result) => {
      if (!result.success) {
        console.warn("Could not load logo for PDF letterhead:", result.message);
        return null;
      }
      return new Promise((resolve) => {
        const img = new Image();
        img.onload = () => {
          try {
            const maxDim = 200;
            const scale2 = Math.min(1, maxDim / Math.max(img.naturalWidth, img.naturalHeight));
            const canvas = document.createElement("canvas");
            canvas.width = img.naturalWidth * scale2;
            canvas.height = img.naturalHeight * scale2;
            canvas.getContext("2d").drawImage(img, 0, 0, canvas.width, canvas.height);
            cachedLogoBase64 = canvas.toDataURL("image/png");
            resolve(cachedLogoBase64);
          } catch (err) {
            console.warn("Could not downscale logo for PDF letterhead:", err.message);
            resolve(result.dataUrl);
          }
        };
        img.onerror = () => resolve(result.dataUrl);
        img.src = result.dataUrl;
      });
    });
  }
